//===============================================================================

function getURLParameter(url, name, defaultValue) {
	if (!url)
		return defaultValue;

	if (url.indexOf("?") == -1)
		return defaultValue;

	var param = defaultValue;
	var paramsString = url.substring(url.indexOf("?") + 1, url.length);
	var params = paramsString.split("&");
	for (var i = 0; i < params.length; i++) {
		if (params[i].indexOf(name + '=') != 0)
			continue;

		param = params[i].substring(
			(name + '=').length, params[i].length);
		break;
	}

	return param;
}

var EU_MAX_DATA_SIZE_MB = ((typeof EU_MAX_DATA_SIZE_MB) != 'undefined') ?
	EU_MAX_DATA_SIZE_MB : parseInt(
		getURLParameter(location.href, 'maxDataSize', '5'));
var EU_LOG_EVENTS = getURLParameter(location.href, 'log', "false") == "true" ?
	true : false;
var EU_DEBUG = getURLParameter(location.href, 'debug', "false") == "true" ?
	true : false;

