			certificates.push(uaKEPCertPtr.toArray());
		if (intCertPtr != null)
			certificates.push(intCertPtr.toArray());
		if (ecdsaCertPtr != null)
			certificates.push(ecdsaCertPtr.toArray());

		return certificates;
