//-------------------------------------------------------------------------------

EndUser.prototype.GeneratePrivateKeyBinary = function(
	password, uaKeysType, uaDSKeysSpec, useDSKeyAsKEP, uaKEPKeysSpec,
	uaParamsPath, internationalKeysType, internationalKeysSpec,
	internationalParamsPath, endUserInfo, extKeyUsages,
	onSuccess, onError) {
	try {
		var euSign = this.m_euSign;
		if (endUserInfo) {
			endUserInfo = EndUserInitFromTransferableObject(
				endUserInfo, EndUserInfo);
		}

		var result = euSign.GeneratePrivateKey(password,
			uaKeysType, uaDSKeysSpec, useDSKeyAsKEP, uaKEPKeysSpec,
			internationalKeysType, internationalKeysSpec,
			endUserInfo, extKeyUsages);

		var _mapRequest = function(type, data, fileName) {
			var request = euSign.GetCRInfo(data).GetTransferableObject();
			request.type = type;
			request.data = data;
			request.fileName = fileName;
			return request;
		};

		var key = result.GetPrivateKey();
		var requests = [];
		var request;
		if (result.GetUARequest()) {
			request = _mapRequest(
				EU_KEYS_REQUEST_TYPE_UA_DS,
				result.GetUARequest(),
				result.GetUARequestName()
			);
			requests.push(request);
		}

		if (result.GetUAKEPRequest()) {
			request = _mapRequest(
				EU_KEYS_REQUEST_TYPE_UA_KEP,
				result.GetUAKEPRequest(),
				result.GetUAKEPRequestName()
			);
			requests.push(request);
		}

		if (result.GetInternationalRequest()) {
			request = _mapRequest(
				EU_KEYS_REQUEST_TYPE_INT_RSA,
				result.GetInternationalRequest(),
				result.GetInternationalRequestName()
			);
			requests.push(request);
		}

		onSuccess({
			"key": key,
			"requests": requests
		});
	} catch (e) {
		onError(e);
	}
};

