//-------------------------------------------------------------------------------

EndUser.prototype.HashData = function(
	hashAlgo, data, asBase64String, onSuccess, onError) {
	var euSign = this.m_euSign;
	var hashContext = null;

	try {
		var datas = DataToNamedDataArray(data);
		var hashes = [];

		for (var i = 0; i < datas.length; i++) {
			var hash = euSign.CtxHashData(
				this.m_context, hashAlgo, null,
				datas[i].val, asBase64String);
			hashes.push(hash);
		}

		var result = DataToResult(data, hashes);
		onSuccess(result);
	} catch (e) {
		if (hashContext)
			euSign.CtxFreeHash(hashContext);

		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.GetSigner = function(sign, signIndex, resolveOIDs,
	onSuccess, onError) {
	var euSign = this.m_euSign;
	var context = null;

	try {
		var signerInfo = null;
		var result = null;

		signIndex = GetOptionalParam(signIndex, -1);
		resolveOIDs = GetOptionalParam(resolveOIDs, false);

		context = euSign.CtxCreate();
		euSign.CtxSetParameter(context,
			EU_RESOLVE_OIDS_CONTEXT_PARAMETER, resolveOIDs);

		if (signIndex == -1) {
			result = [];
			var signCount = euSign.CtxGetSignsCount(
				context, sign);
			for (var i = 0; i < signCount; i++) {
				signerInfo = euSign.CtxGetSignerInfo(
					context, i, sign);
				result.push(signerInfo.GetTransferableObject());
			}
		} else {
			signerInfo = euSign.CtxGetSignerInfo(
				context, signIndex, sign);
			result = signerInfo.GetTransferableObject();
		}

		euSign.CtxFree(context);

		onSuccess(result);
	} catch (e) {
		if (context)
			euSign.CtxFree(context);

		onError(e);
	}
};

