//-------------------------------------------------------------------------------

EndUser.prototype.VerifyHash = function(
	hash, sign, signIndex, onSuccess, onError) {
	try {
		var onTime = null;
		var offline = false;
		var noCRL = false;
		var signInfo = null;
		var result = null;

		signIndex = GetOptionalParam(signIndex, -1);

		if (signIndex == -1) {
			result = [];
			var signCount = this.m_euSign.CtxGetSignsCount(
				this.m_context, sign);
			for (var i = 0; i < signCount; i++) {
				signInfo = this.m_euSign.VerifyHashOnTimeEx(
					hash, i, sign, onTime, offline, noCRL);
				signInfo = signInfo.GetTransferableObject();
				signInfo.signLevel = this.m_euSign.GetSignType(
					i, sign);
				result.push(signInfo);
			}
		} else {
			signInfo = this.m_euSign.VerifyHashOnTimeEx(
				hash, signIndex, sign, onTime, offline, noCRL);
			signInfo = signInfo.GetTransferableObject();
			signInfo.signLevel = this.m_euSign.GetSignType(
				signIndex, sign);
			result = signInfo;
		}

		onSuccess(result);
	} catch (e) {
		onError(e);
	}
};

