//-------------------------------------------------------------------------------

EndUser.prototype.CtxGetOwnCertificates = function(
	privateKeyContext, onSuccess, onError) {
	try {
		var euSign = this.m_euSign;
		var index = 0;
		var cert = null;
		var certs = [];

		if (privateKeyContext == null) {
			euSign.RaiseError(EU_ERROR_BAD_CERT);
			return;
		}

		privateKeyContext = EndUserInitFromTransferableObject(
			privateKeyContext, EndUserPrivateKeyContext);

		while ((cert = euSign.CtxEnumOwnCertificates(
					privateKeyContext, index)) != null) {
			certs.push(cert.GetTransferableObject());
			index++;
		}

		onSuccess(certs);
	} catch (e) {
		onError(e);
	}
};

