EndUser.prototype.ASiCSignData = function(
	signAlgo, asicType, signType, signLevel, references,
	asBase64String, onSuccess, onError) {
	Debug("EndUser::ASiCSignData", arguments);

	if (this.m_euKSP.IsPrivateKeyReaded()) {
		this.m_euKSP.ASiCSignData(
			signAlgo, asicType, signType, signLevel, references,
			asBase64String, onSuccess, onError);
		return;
	}

	var pThis = this;
	var euSign = pThis.m_euSign;
	var pkContext = pThis.m_pkContext;

	try {
		if (pkContext == null) {
			euSign.RaiseError(EU_ERROR_BAD_CERT);
			return;
		}

		pkContext = EndUserInitFromTransferableObject(
			pkContext, EndUserPrivateKeyContext);

		references = DataToNamedDataArray(references);
		var asicReferences = [];
		for (var i = 0; i < references.length; i++) {
			var reference = new EndUserReference(
				references[i].name, references[i].val);
			asicReferences.push(reference);
		}

		var asicData = euSign.CtxASiCSignData(pkContext,
			signAlgo, asicType, signType, signLevel,
			asicReferences, asBase64String);
		var result = {
			name: references[0].name +
				(asicType == EU_ASIC_TYPE_S ?
					'.asics' : '.asice'),
			val: asicData
		};
		onSuccess(result);
	} catch (e) {
		onError(e);
	}
};

